class Solution { private val choices=hashMapOf<String,MutableList<Char>>();fun pyramidTransition(bottom:String,allowed:List<String>):Boolean{for(rule in allowed)choices.getOrPut(rule.substring(0,2)){mutableListOf()}.add(rule[2]);return solve(bottom)};private fun solve(row:String):Boolean{if(row.length==1)return true;return build(row,0,StringBuilder())};private fun build(row:String,position:Int,next:StringBuilder):Boolean{if(position==row.length-1)return solve(next.toString());val options=choices[row.substring(position,position+2)]?:return false;for(c in options){next.append(c);if(build(row,position+1,next))return true;next.setLength(next.length-1)};return false} }
